style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
body {
    background: url("https://i.imgur.com/qChmH2M.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #ffffff !important;
  }

  .container-main, .navbar, .footer-container, .content, .game-home-page, .game-page, .container-footer {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }

  a {
    color: #a78bfa !important;
  }

  .btn-primary, .btn-growth-sm {
    background-color: #8b5cf6 !important;
    border-color: #8b5cf6 !important;
    color: #fff !important;
  }

  .ad-container, .advertisement, .games-ad, .trending-container {
    display: none !important;
  }
}
